  name: string
  description: string
  userInvocable?: boolean
  disableModelInvocation?: boolean
  body: string
}

// 项目 MCP 表单数据
export interface ProjectMCPFormData {
  name: string
  type: 'stdio' | 'http'
  command?: string
  args?: string[]
  url?: string
  env?: Record<string, string>
}

// 项目 Command 表单数据
export interface ProjectCommandFormData {
  name: string
  description: string
  body: string
}

// 项目 Hook 表单数据
export interface ProjectHookFormData {
  event: string
  matcher?: string
  command: string
}

